-- демо-каталог, чтобы свежая база (прод, docker-compose) не открывалась пустым магазином.
-- выгрузил из своей локальной базы: бренды, дерево категорий, активные товары, переводы и фото в S3.
-- пользователей и заказов тут нет, админа создаёт AdminInitializer.
-- всё связываю по slug и названию бренда, а не по id, так миграция не зависит от того, какие id выдала база

INSERT INTO brands (name, description, logo_url) VALUES
    ('Starboard', 'Innovation quality since 1994', NULL),
