-- ord нужен, чтобы товары получили id в том же порядке, что и у меня локально
INSERT INTO products (name, slug, description, price, compare_at_price, quantity, brand_id, category_id, board_type, sku)
SELECT v.name, v.slug, v.description, v.price, v.compare_at_price, v.quantity, b.id, c.id, v.board_type, v.sku
FROM (VALUES
    (1, 'Red Paddle Co 10''6" Ride MSL', 'red-paddle-co-10-6-ride-msl', 'The board most people start with and never want to swap. Wide enough to feel calm on the first day, still fun once you can paddle properly.', 15990.00, NULL, 8, 'Red Paddle Co', 'inflatable-boards', 'INFLATABLE', NULL),
    (2, 'Starboard iGO One 10''8" x 33" With Paddle', 'starboard-igo-one-10-8-x-33', 'Simple and stable inflatable for beginners and families. Comes with a paddle, so you can go to the lake the same day.', 12990.00, NULL, 6, 'Starboard', 'inflatable-boards', 'INFLATABLE', NULL),
    (3, 'Fanatic iSUP Fly Air SLT 10''4"', 'fanatic-isup-fly-air-slt-10-4', 'Light allround inflatable that rolls up small, good for a car boot or a flat. Handles small waves too.', 8990.00, 9990.00, 2, 'Fanatic', 'inflatable-boards', 'INFLATABLE', NULL),
    (4, 'Starboard Generation 12''6" x 28"', 'starboard-generation-12-6-x-28', 'A mix of touring, racing and surfing board in one shape. A good first hard board if you want one board for everything.', 28290.00, NULL, 3, 'Starboard', 'composite-boards', 'HARDBOARD', NULL),
    (5, 'SIC Maui Okeanos 12''6" x 29"', 'sic-maui-okeanos-12-6-x-29', 'Touring hard board that keeps a straight line and glides well on long distances. Stable enough for open water.', 31990.00, NULL, 2, 'SIC Maui', 'composite-boards', 'HARDBOARD', NULL),
    (6, 'Starboard All Star 14''0" x 23"', 'starboard-all-star-14-0-x-23', 'Race board for flat water and choppy conditions. For people who already train and want to get faster.', 81890.00, NULL, 1, 'Starboard', 'touring-race', 'HARDBOARD', NULL),
    (7, 'Red Paddle Co 14''0" Voyager MSL', 'red-paddle-co-14-0-voyager-msl', 'Long inflatable for trips on rivers and lakes. Tracks straight and has room for bags on the nose.', 26990.00, NULL, 4, 'Red Paddle Co', 'touring-race', 'INFLATABLE', NULL),
    (8, 'Fanatic iSUP Ray Air SLT', 'fanatic-isup-ray-air-slt', 'Narrow inflatable for touring and first races. Faster than an allround board, but needs a bit more balance.', 10290.00, NULL, 1, 'Fanatic', 'touring-race', 'INFLATABLE', NULL),
    (9, 'Red Paddle Co Hybrid 3-Piece Carbon Paddle', 'red-paddle-co-hybrid-3-piece-carbon-paddle', 'Three-piece adjustable paddle from carbon and fibreglass. Packs into the board bag and is lighter than basic aluminium paddles.', 4590.00, NULL, 10, 'Red Paddle Co', 'paddles', NULL, NULL),
    (10, 'Starboard Enduro Carbon Paddle', 'starboard-enduro-carbon-paddle', 'Carbon paddle with a powerful blade, works for flat water and waves. Good upgrade from a plastic paddle.', 4290.00, NULL, 7, 'Starboard', 'paddles', NULL, NULL),
    (11, 'NSP Vivace 79 Carbon Paddle', 'nsp-vivace-79-carbon-paddle', 'Full carbon paddle for racing and fitness paddling. Very light, the medium blade size fits most riders.', 6790.00, 7590.00, 3, 'NSP', 'paddles', NULL, NULL),
    (12, 'Starboard Semi-Coil Leash 9ft', 'starboard-semi-coil-leash-9ft', 'Leash that stays on the deck and does not drag in the water. Ankle or calf strap.', 1090.00, NULL, 15, 'Starboard', 'sup-accessories', NULL, NULL),
    (13, 'Red Paddle Co SUP Shoulder Carry Strap', 'red-paddle-co-sup-shoulder-carry-strap', 'Strap for carrying an inflated board on your shoulder from the car to the water.', 490.00, NULL, 12, 'Red Paddle Co', 'sup-accessories', NULL, NULL),
    (14, 'Starboard FreeWing AIR v5 4.5m', 'starboard-freewing-air-v5-4-5m', 'Allround wing for cruising, waves and first jumps. 4.5 m is a popular size for average wind.', 21990.00, 23990.00, 3, 'Starboard', 'wings', NULL, NULL),
    (15, 'SIC Maui Dragon 5.0m', 'sic-maui-dragon-5-0m', 'Freeride wing with stable handling, easy to pump onto the foil. Good choice for lighter wind days.', 19490.00, NULL, 2, 'SIC Maui', 'wings', NULL, NULL),
    (16, 'Starboard Take Off Foilboard 90L', 'starboard-take-off-foilboard-90l', 'Compact wing foil board that lifts early and turns quickly. For riders who already foil and want something sportier.', 40990.00, NULL, 1, 'Starboard', 'foil-boards', NULL, NULL),
    (17, 'SIC Maui Halau 7''0"', 'sic-maui-halau-7-0', 'Longer foil board for downwind and SUP foiling. Extra length helps to get up on the foil.', 31190.00, NULL, 2, 'SIC Maui', 'foil-boards', NULL, NULL),
    (18, 'Starboard X-15 Class UCS Foil Pack', 'starboard-x-15-class-ucs-foil-pack', 'Complete foil set: carbon mast, front wing and tail wing. Made for wing foil racing in the X-15 class.', 66290.00, NULL, 1, 'Starboard', 'foils', NULL, NULL),
    (19, 'SIC Maui Slash Foil 1700 Complete', 'sic-maui-slash-foil-1700-complete', 'Big front wing that lifts at low speed. Good first foil for SUP and wing foiling.', 25390.00, NULL, 3, 'SIC Maui', 'foils', NULL, NULL),
    (20, 'SIC Maui Pick Pocket 7''4"', 'sic-maui-pick-pocket-7-4', 'Mid-length surfboard that catches small waves easily. Forgiving for surfers who are still learning.', 14590.00, NULL, 2, 'SIC Maui', 'surfboards', NULL, NULL),
    (21, 'NSP Funboard Elements 7''6"', 'nsp-funboard-elements-7-6', 'Classic funboard for beginners: lots of volume, stable and paddles into waves without much effort.', 10690.00, NULL, 4, 'NSP', 'surfboards', NULL, NULL),
    (22, 'Red Paddle Co 10ft Surf Leash', 'red-paddle-co-10ft-surf-leash', 'Strong 7 mm leash for taking a board into the surf. Swivels on both ends so it does not twist.', 790.00, NULL, 20, 'Red Paddle Co', 'surf-accessories', NULL, NULL),
    (23, 'SIC Maui Foil Board Bag 6''0" x 22"', 'sic-maui-foil-board-bag-6-0-x-22', 'Padded bag for a foil or small surf board. Protects the rails in the car and on trips.', 2890.00, NULL, 5, 'SIC Maui', 'surf-accessories', NULL, NULL),
    (24, 'Starboard Men Iconic Tee', 'starboard-men-iconic-tee', 'Soft organic cotton T-shirt with the Starboard logo. For the beach and after the session.', 690.00, NULL, 25, 'Starboard', 'mens-clothing', NULL, NULL),
    (25, 'Red Paddle Co Men''s Performance T-Shirt', 'red-paddle-co-mens-performance-t-shirt', 'Quick dry T-shirt for paddling and the gym. Takes sweat away and dries fast.', 390.00, NULL, 18, 'Red Paddle Co', 'mens-clothing', NULL, NULL),
    (26, 'Red Paddle Co Women''s Performance Long Sleeve Top', 'red-paddle-co-womens-performance-long-sleeve-top', 'Breathable long sleeve top for cool mornings on the water. Works as a base layer too.', 990.00, NULL, 9, 'Red Paddle Co', 'womens-clothing', NULL, NULL),
    (27, 'Red Paddle Co Women''s Active Jacket', 'red-paddle-co-womens-active-jacket', 'Light stretchy jacket that packs into its own pocket. For paddling, bike or a walk.', 490.00, 1090.00, 4, 'Red Paddle Co', 'womens-clothing', NULL, NULL),
    (28, 'Red Paddle Co Men''s Alter EVO Changing Robe', 'red-paddle-co-mens-alter-evo-changing-robe', 'Waterproof changing robe with warm fleece inside. Lets you change on the shore in wind and rain.', 3690.00, NULL, 6, 'Red Paddle Co', 'changing-robes', NULL, NULL),
    (29, 'Red Paddle Co Women''s Quick Dry Poncho', 'red-paddle-co-womens-quick-dry-poncho', 'Microfibre towel poncho with a hood. Dries you quickly and packs small for summer.', 890.00, NULL, 10, 'Red Paddle Co', 'changing-robes', NULL, NULL),
    (30, 'Starboard Double Action Tiki Pump', 'starboard-double-action-tiki-pump', 'Hand pump that pushes air on both strokes, so you reach board pressure faster. Has a manometer.', 990.00, NULL, 14, 'Starboard', 'pumps', NULL, NULL),
    (31, 'SIC Maui SUP Air Pump', 'sic-maui-sup-air-pump', 'Simple hand pump for inflatable SUPs and wings, with a pressure gauge.', 890.00, NULL, 8, 'SIC Maui', 'pumps', NULL, NULL),
    (32, 'Red Paddle Co Roll Top Dry Bag Backpack 30L', 'red-paddle-co-roll-top-dry-bag-backpack-30l', 'Waterproof roll top bag with shoulder straps. Fits clothes, food and a phone for a day trip.', 790.00, NULL, 16, 'Red Paddle Co', 'waterproof-bags', NULL, NULL),
    (33, 'Red Paddle Co Adventure Waterproof Backpack 12L', 'red-paddle-co-adventure-waterproof-backpack-12l', 'Small waterproof backpack for everyday use and short trips on the water.', 1390.00, NULL, 7, 'Red Paddle Co', 'waterproof-bags', NULL, NULL),
    (34, 'Red Paddle Co SUP Buoyancy Aid', 'red-paddle-co-sup-buoyancy-aid', 'Buoyancy aid with big arm holes, so it does not get in the way while paddling.', 2290.00, NULL, 6, 'Red Paddle Co', 'buoyancy-aids', NULL, NULL),
    (35, 'Starboard Life Jacket', 'starboard-life-jacket', 'Affordable foam life jacket with buckles and a zip. Light and comfortable even when wet.', 1790.00, NULL, 9, 'Starboard', 'buoyancy-aids', NULL, NULL),
    (36, 'SIC Maui Roof Rack Straps 13ft', 'sic-maui-roof-rack-straps-13ft', 'Pair of straps for fixing boards to the roof rack of a car.', 690.00, NULL, 20, 'SIC Maui', 'car-transport', NULL, NULL),
    (37, 'Red Paddle Co ATB Board Bag', 'red-paddle-co-atb-board-bag', 'Big backpack for a rolled inflatable board, paddle and pump. Has padded straps for longer walks.', 2190.00, NULL, 5, 'Red Paddle Co', 'car-transport', NULL, NULL)
) AS v(ord, name, slug, description, price, compare_at_price, quantity, brand, category, board_type, sku)
JOIN brands b ON b.name = v.brand
JOIN categories c ON c.slug = v.category
ORDER BY v.ord;

INSERT INTO product_translations (product_id, lang, name, description)
SELECT p.id, v.lang, v.name, v.description
FROM (VALUES
    ('red-paddle-co-10-6-ride-msl', 'ro', NULL, 'Placa cu care încep cei mai mulți și pe care nu mai vor s-o schimbe. Destul de lată ca să vă simțiți liniștit din prima zi și tot distractivă când vâsliți deja bine.'),
    ('red-paddle-co-10-6-ride-msl', 'ru', NULL, 'Доска, с которой начинает большинство и потом не хочет менять. Достаточно широкая, чтобы спокойно стоять в первый день, и всё ещё интересная, когда уже уверенно гребёте.'),
    ('starboard-igo-one-10-8-x-33', 'ro', NULL, 'Placă gonflabilă simplă și stabilă pentru începători și familii. Vine cu vâslă, deci puteți merge la lac chiar în aceeași zi.'),
    ('starboard-igo-one-10-8-x-33', 'ru', NULL, 'Простая и устойчивая надувная доска для новичков и семей. Идёт с веслом, так что на озеро можно поехать в тот же день.'),
    ('fanatic-isup-fly-air-slt-10-4', 'ro', NULL, 'Placă gonflabilă universală și ușoară, care se strânge mic, încape în portbagaj sau într-un apartament. Se descurcă și pe valuri mici.'),
    ('fanatic-isup-fly-air-slt-10-4', 'ru', NULL, 'Лёгкая универсальная надувная доска, сворачивается компактно и помещается в багажник или квартиру. Справляется и с небольшой волной.'),
    ('starboard-generation-12-6-x-28', 'ro', NULL, 'Turism, curse și surf într-o singură formă. O primă placă rigidă bună dacă vreți una pentru toate.'),
    ('starboard-generation-12-6-x-28', 'ru', NULL, 'Туринг, гонки и сёрфинг в одной форме. Хорошая первая жёсткая доска, если нужна одна на всё.'),
    ('sic-maui-okeanos-12-6-x-29', 'ro', NULL, 'Placă rigidă de turism care ține linia dreaptă și alunecă bine pe distanțe lungi. Destul de stabilă pentru apă deschisă.'),
    ('sic-maui-okeanos-12-6-x-29', 'ru', NULL, 'Жёсткая туринговая доска: держит прямую и хорошо катится на длинных дистанциях. Достаточно устойчивая для открытой воды.'),
    ('starboard-all-star-14-0-x-23', 'ro', NULL, 'Placă de curse pentru apă plată și valuri scurte. Pentru cei care se antrenează deja și vor să fie mai rapizi.'),
    ('starboard-all-star-14-0-x-23', 'ru', NULL, 'Гоночная доска для гладкой воды и короткой волны. Для тех, кто уже тренируется и хочет ехать быстрее.'),
    ('red-paddle-co-14-0-voyager-msl', 'ro', NULL, 'Placă gonflabilă lungă pentru excursii pe râuri și lacuri. Merge drept și are loc pentru bagaje în față.'),
    ('red-paddle-co-14-0-voyager-msl', 'ru', NULL, 'Длинная надувная доска для походов по рекам и озёрам. Идёт прямо, на носу есть место для сумок.'),
    ('fanatic-isup-ray-air-slt', 'ro', NULL, 'Placă gonflabilă îngustă pentru turism și primele curse. Mai rapidă decât una universală, dar cere ceva mai mult echilibru.'),
    ('fanatic-isup-ray-air-slt', 'ru', NULL, 'Узкая надувная доска для туринга и первых гонок. Быстрее универсальной, но требует чуть больше баланса.'),
    ('red-paddle-co-hybrid-3-piece-carbon-paddle', 'ro', NULL, 'Vâslă reglabilă din trei bucăți, din carbon și fibră de sticlă. Încape în geanta plăcii și e mai ușoară decât vâslele simple din aluminiu.'),
    ('red-paddle-co-hybrid-3-piece-carbon-paddle', 'ru', NULL, 'Регулируемое трёхсоставное весло из карбона и стеклоткани. Помещается в сумку от доски и легче простых алюминиевых вёсел.'),
    ('starboard-enduro-carbon-paddle', 'ro', NULL, 'Vâslă din carbon cu lamă puternică, pentru apă plată și valuri. Un upgrade bun după o vâslă din plastic.'),
    ('starboard-enduro-carbon-paddle', 'ru', NULL, 'Карбоновое весло с мощной лопастью, для гладкой воды и волн. Хороший апгрейд после пластикового весла.'),
    ('nsp-vivace-79-carbon-paddle', 'ro', NULL, 'Vâslă integral din carbon pentru curse și fitness. Foarte ușoară, iar lama de mărime medie se potrivește majorității.'),
    ('nsp-vivace-79-carbon-paddle', 'ru', NULL, 'Полностью карбоновое весло для гонок и фитнеса. Очень лёгкое, средняя лопасть подходит большинству.'),
    ('starboard-semi-coil-leash-9ft', 'ro', NULL, 'Leash care stă pe punte și nu se târăște prin apă. Se prinde de gleznă sau de gambă.'),
    ('starboard-semi-coil-leash-9ft', 'ru', NULL, 'Лиш, который лежит на деке и не тянется по воде. Крепится на лодыжку или икру.'),
    ('red-paddle-co-sup-shoulder-carry-strap', 'ro', NULL, 'Curea pentru a duce placa umflată pe umăr de la mașină până la apă.'),
    ('red-paddle-co-sup-shoulder-carry-strap', 'ru', NULL, 'Ремень, чтобы нести накачанную доску на плече от машины до воды.'),
    ('starboard-freewing-air-v5-4-5m', 'ro', NULL, 'Wing universal pentru plimbări, valuri și primele sărituri. 4,5 m este o mărime populară pentru vânt mediu.'),
    ('starboard-freewing-air-v5-4-5m', 'ru', NULL, 'Универсальное крыло для покатушек, волн и первых прыжков. 4,5 м — популярный размер для среднего ветра.'),
    ('sic-maui-dragon-5-0m', 'ro', NULL, 'Wing freeride cu control stabil, ușor de pompat până pe foil. O alegere bună pentru zilele cu vânt slab.'),
    ('sic-maui-dragon-5-0m', 'ru', NULL, 'Фрирайдное крыло со стабильным управлением, на фойл выходит легко. Хороший выбор для слабого ветра.'),
    ('starboard-take-off-foilboard-90l', 'ro', NULL, 'Placă compactă de wing foil care se ridică devreme și virează repede. Pentru cei care merg deja pe foil și vor ceva mai sportiv.'),
    ('starboard-take-off-foilboard-90l', 'ru', NULL, 'Компактная доска для винг-фойла: рано выходит на крыло и быстро поворачивает. Для тех, кто уже катается на фойле и хочет что-то спортивнее.'),
    ('sic-maui-halau-7-0', 'ro', NULL, 'Placă foil mai lungă pentru downwind și SUP foil. Lungimea în plus ajută să ieșiți pe foil.'),
    ('sic-maui-halau-7-0', 'ru', NULL, 'Удлинённая фойл-доска для даунвинда и SUP-фойла. Лишняя длина помогает выйти на фойл.'),
    ('starboard-x-15-class-ucs-foil-pack', 'ro', NULL, 'Set complet de foil: catarg din carbon, aripă frontală și aripă spate. Făcut pentru curse de wing foil în clasa X-15.'),
    ('starboard-x-15-class-ucs-foil-pack', 'ru', NULL, 'Полный комплект фойла: карбоновая мачта, переднее и заднее крыло. Сделан для гонок по винг-фойлу в классе X-15.'),
    ('sic-maui-slash-foil-1700-complete', 'ro', NULL, 'Aripă frontală mare care se ridică la viteză mică. Un prim foil bun pentru SUP și wing foiling.'),
    ('sic-maui-slash-foil-1700-complete', 'ru', NULL, 'Большое переднее крыло, которое поднимает на малой скорости. Хороший первый фойл для SUP и винг-фойла.'),
    ('sic-maui-pick-pocket-7-4', 'ro', NULL, 'Placă de surf de lungime medie care prinde ușor valurile mici. Iertătoare pentru cei care încă învață.'),
    ('sic-maui-pick-pocket-7-4', 'ru', NULL, 'Сёрфборд средней длины, легко ловит маленькие волны. Прощает ошибки тем, кто ещё учится.'),
    ('nsp-funboard-elements-7-6', 'ro', NULL, 'Funboard clasic pentru începători: mult volum, stabil și intră în val fără mult efort.'),
    ('nsp-funboard-elements-7-6', 'ru', NULL, 'Классический фанборд для новичков: большой объём, устойчивый и легко заходит в волну.'),
    ('red-paddle-co-10ft-surf-leash', 'ro', NULL, 'Leash rezistent de 7 mm pentru surf. Are vârtejuri la ambele capete, deci nu se răsucește.'),
    ('red-paddle-co-10ft-surf-leash', 'ru', NULL, 'Прочный лиш 7 мм для сёрфинга. Вертлюги на обоих концах, поэтому не перекручивается.'),
    ('sic-maui-foil-board-bag-6-0-x-22', 'ro', NULL, 'Husă căptușită pentru o placă foil sau o placă de surf mică. Protejează marginile în mașină și în călătorii.'),
    ('sic-maui-foil-board-bag-6-0-x-22', 'ru', NULL, 'Мягкий чехол для фойл-доски или небольшого сёрфборда. Бережёт канты в машине и в поездках.'),
    ('starboard-men-iconic-tee', 'ro', NULL, 'Tricou moale din bumbac organic cu logo Starboard. Pentru plajă și după sesiune.'),
    ('starboard-men-iconic-tee', 'ru', NULL, 'Мягкая футболка из органического хлопка с логотипом Starboard. Для пляжа и после катания.'),
    ('red-paddle-co-mens-performance-t-shirt', 'ro', NULL, 'Tricou cu uscare rapidă pentru vâslit și sală. Elimină transpirația și se usucă repede.'),
    ('red-paddle-co-mens-performance-t-shirt', 'ru', NULL, 'Быстросохнущая футболка для гребли и зала. Отводит пот и быстро сохнет.'),
    ('red-paddle-co-womens-performance-long-sleeve-top', 'ro', NULL, 'Bluză respirabilă cu mânecă lungă pentru diminețile răcoroase pe apă. Merge și ca strat de bază.'),
    ('red-paddle-co-womens-performance-long-sleeve-top', 'ru', NULL, 'Дышащий лонгслив для прохладных утр на воде. Подходит и как базовый слой.'),
    ('red-paddle-co-womens-active-jacket', 'ro', NULL, 'Jachetă ușoară și elastică, se strânge în propriul buzunar. Pentru vâslit, bicicletă sau plimbare.'),
    ('red-paddle-co-womens-active-jacket', 'ru', NULL, 'Лёгкая тянущаяся куртка, складывается в собственный карман. Для гребли, велосипеда или прогулки.'),
    ('red-paddle-co-mens-alter-evo-changing-robe', 'ro', NULL, 'Poncho impermeabil cu fleece cald înăuntru. Vă puteți schimba pe mal pe vânt și ploaie.'),
    ('red-paddle-co-mens-alter-evo-changing-robe', 'ru', NULL, 'Непромокаемое пончо с тёплым флисом внутри. Переодеться на берегу можно даже в ветер и дождь.'),
    ('red-paddle-co-womens-quick-dry-poncho', 'ro', NULL, 'Poncho-prosop din microfibră, cu glugă. Vă usucă repede și se strânge mic pentru vară.'),
    ('red-paddle-co-womens-quick-dry-poncho', 'ru', NULL, 'Пончо-полотенце из микрофибры с капюшоном. Быстро вытирает и компактно складывается на лето.'),
    ('starboard-double-action-tiki-pump', 'ro', NULL, 'Pompă manuală care împinge aer la ambele mișcări, deci ajungeți mai repede la presiunea plăcii. Are manometru.'),
    ('starboard-double-action-tiki-pump', 'ru', NULL, 'Ручной насос, который качает в обе стороны, поэтому до нужного давления быстрее. С манометром.'),
    ('sic-maui-sup-air-pump', 'ro', NULL, 'Pompă manuală simplă pentru plăci SUP gonflabile și wing-uri, cu manometru.'),
    ('sic-maui-sup-air-pump', 'ru', NULL, 'Простой ручной насос для надувных SUP-досок и крыльев, с манометром.'),
    ('red-paddle-co-roll-top-dry-bag-backpack-30l', 'ro', NULL, 'Rucsac impermeabil cu închidere rulată și bretele. Încap haine, mâncare și telefonul pentru o zi pe apă.'),
    ('red-paddle-co-roll-top-dry-bag-backpack-30l', 'ru', NULL, 'Непромокаемый рюкзак с закруткой и лямками. Поместятся одежда, еда и телефон на день на воде.'),
    ('red-paddle-co-adventure-waterproof-backpack-12l', 'ro', NULL, 'Rucsac impermeabil mic pentru fiecare zi și ieșiri scurte pe apă.'),
    ('red-paddle-co-adventure-waterproof-backpack-12l', 'ru', NULL, 'Небольшой непромокаемый рюкзак на каждый день и для коротких выходов на воду.'),
    ('red-paddle-co-sup-buoyancy-aid', 'ro', NULL, 'Vestă de flotabilitate cu decupaje mari pentru brațe, nu încurcă la vâslit.'),
    ('red-paddle-co-sup-buoyancy-aid', 'ru', NULL, 'Страховочный жилет с большими проймами, не мешает грести.'),
    ('starboard-life-jacket', 'ro', NULL, 'Vestă de salvare din spumă, accesibilă, cu catarame și fermoar. Ușoară și comodă chiar și udă.'),
    ('starboard-life-jacket', 'ru', NULL, 'Недорогой спасательный жилет из пены, с пряжками и молнией. Лёгкий и удобный даже мокрым.'),
    ('sic-maui-roof-rack-straps-13ft', 'ro', NULL, 'Pereche de chingi pentru fixarea plăcilor pe portbagajul de plafon al mașinii.'),
    ('sic-maui-roof-rack-straps-13ft', 'ru', NULL, 'Пара строп, чтобы закрепить доски на багажнике машины.'),
    ('red-paddle-co-atb-board-bag', 'ro', NULL, 'Rucsac mare pentru o placă gonflabilă rulată, vâslă și pompă. Are bretele căptușite pentru drumuri mai lungi.'),
    ('red-paddle-co-atb-board-bag', 'ru', NULL, 'Большой рюкзак для свёрнутой надувной доски, весла и насоса. Мягкие лямки для долгих переходов.')
) AS v(slug, lang, name, description)
JOIN products p ON p.slug = v.slug;

